import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

class IsraelEmblem extends StatelessWidget {
  final double height;
  final double? width;

  const IsraelEmblem({super.key, this.height = 54, this.width});

  static final Uint8List _bytes = base64Decode(_base64String);
  static const String _base64String = '';

  @override
  Widget build(BuildContext context) {
    return Image.asset('assets/emblem_of_israel.png', height: height, width: width, fit: BoxFit.contain, filterQuality: FilterQuality.high, errorBuilder: (context, error, stackTrace) => Image.memory(_bytes, height: height, width: width, fit: BoxFit.contain, filterQuality: FilterQuality.high));
  }
}
